# Find stock references to the ten-byte AF target record and the orientation banks.
# Read-only. Do not edit this file after it has run.
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
needles = {
    'ten-byte-a33ca384': bytes.fromhex('84a33ca3'),
    'bank0-a031eaa0': bytes.fromhex('a0ea31a0'),
    'bank1-a031eab0': bytes.fromhex('b0ea31a0'),
    'bank2-a031eac0': bytes.fromhex('c0ea31a0'),
    'exif-store-a33ac4e2': bytes.fromhex('e2c43aa3'),
}
lines = []
for name, needle in needles.items():
    hits = []
    start = 0
    while len(hits) < 12:
        i = img.find(needle, start)
        if i < 0:
            break
        hits.append(f'{(BASE + i):08x}')
        start = i + 1
    lines.append(f'{name} {len(hits)} {" ".join(hits)}')
text = '\n'.join(lines) + '\n'
Path('work/out/scan-record-s5.txt').write_text(text, encoding='utf-8')
print(text)
